 "content": "from collections import deque


def transform(grid):
    """Stamp a 3x3 patch of 1s around each 2 embedded in a 3-region."""
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    boxes = []

    # Find connected 3-regions and their bounding boxes. Embedded 2 markers
    # make holes in otherwise solid rectangular panels, but do not disconnect
    # the remaining 3 cells.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w and not seen[nr][nc] and grid[nr][nc] == 3:
                        seen[nr][nc] = True
                        q.append((nr, nc))
            rows = [p[0] for p in cells]
            cols = [p[1] for p in cells]
            boxes.append((min(rows), max(rows), min(cols), max(cols)))

    out = [row[:] for row in grid]
    centers = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 and any(r0 <= r <= r1 and c0 <= c <= c1 for r0, r1, c0, c1 in boxes):
                centers.append((r, c))

    for r, c in centers:
        for rr in range(max(0, r - 1), min(h, r + 2)):
            for cc in range(max(0, c - 1), min(w, c + 2)):
                if grid[rr][cc] != 2:
                    out[rr][cc] = 1
    return out


if __name__ == "__main__":
    import json
    import sys
    print(json.dumps(transform(json.load(sys.stdin))))

